<?php
declare(strict_types=1);session_start();$base=dirname(__DIR__);$creds=require $base.'/cron/private/discovery-admin.php';
if(!isset($_SERVER['PHP_AUTH_USER'])||!hash_equals($creds['username'],(string)$_SERVER['PHP_AUTH_USER'])||!hash_equals($creds['password'],(string)($_SERVER['PHP_AUTH_PW']??''))){header('WWW-Authenticate: Basic realm="Revue sources RGPD"');header('HTTP/1.0 401 Unauthorized');echo 'Authentification requise';exit;}
$candFile=$base.'/cron/private/candidates.json';$obsFile=$base.'/cron/private/observations-private.json';$c=json_decode((string)file_get_contents($candFile),true,512,JSON_THROW_ON_ERROR);$d=json_decode((string)file_get_contents($obsFile),true,512,JSON_THROW_ON_ERROR);$_SESSION['csrf']=$_SESSION['csrf']??bin2hex(random_bytes(20));$msg='';
function savejson(string $f,array $v):void{$tmp=$f.'.tmp';file_put_contents($tmp,json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);rename($tmp,$f);}function sid(string $u):string{return 'discovery-'.substr(hash('sha256',$u.microtime(true)),0,12);}function h($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf'],(string)($_POST['csrf']??'')))die('CSRF');$id=(string)($_POST['id']??'');foreach($c['candidates'] as &$x){if($x['id']!==$id)continue;$action=$_POST['action']??'';if($action==='reject'){$x['status']='rejected';$x['reviewed_at']=date(DATE_ATOM);$msg='Source refusée.';}elseif($action==='watch'){$x['status']='monitored_no_price';$x['reviewed_at']=date(DATE_ATOM);$msg='Source conservée en surveillance.';}elseif($action==='approve'){$value=(float)str_replace(',','.',preg_replace('/[^0-9,.]/','',(string)($_POST['value']??'')));if($value<=0){$msg='Prix invalide.';break;}$scope=in_array($_POST['scope']??'', ['market','dpo','legal'],true)?$_POST['scope']:'market';$obs=['id'=>sid($x['url']),'provider'=>trim((string)($_POST['provider']??parse_url($x['url'],PHP_URL_HOST))),'provider_type'=>trim((string)($_POST['provider_type']??'Prestataire')),'service_family'=>trim((string)($_POST['service']??'Audit RGPD')),'client_segment'=>trim((string)($_POST['segment']??'TPE / PME')),'unit'=>$_POST['unit']??'EUR/mission','value'=>$value,'price_text'=>trim((string)($_POST['price_text']??($value.' €'))),'included'=>$scope==='market','checked'=>date('Y-m-d'),'source'=>$x['url'],'note'=>'Source validée manuellement depuis le module de découverte.','comparison_scope'=>$scope,'provider_region'=>($x['region']==='moselle'?'grand-est':$x['region']),'provider_department'=>$x['department']??'','provider_city'=>$x['city']??'','crawl_mode'=>'manual_review'];$d['observations'][]=$obs;$x['status']='approved';$x['approved_observation_id']=$obs['id'];$x['reviewed_at']=date(DATE_ATOM);savejson($obsFile,$d);require_once $base.'/cron/lib-comparator.php';rgpd_rebuild_public($base);$msg='Source ajoutée et comparateur recalculé.';}break;}unset($x);savejson($candFile,$c);}
$filter=$_GET['status']??'review';$rows=array_filter($c['candidates'],function($x)use($filter){if($filter==='all')return true;if($filter==='review')return in_array($x['status'],['new','needs_price_review'],true);return $x['status']===$filter;});
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revue des sources RGPD</title><style>body{font:15px/1.45 system-ui;margin:0;background:#f3f3ef;color:#20231f}.wrap{width:min(1180px,calc(100% - 28px));margin:30px auto}h1{font-size:32px}.nav a{margin-right:10px}.msg{background:#e2ece4;padding:12px;border-radius:10px}.card{background:#fff;border:1px solid #ddd;border-radius:16px;padding:18px;margin:14px 0}.meta{color:#69706a}.prices{display:flex;gap:6px;flex-wrap:wrap}.prices span{background:#edf2ed;padding:5px 8px;border-radius:999px}form.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px}input,select,button{padding:9px;border:1px solid #ccc;border-radius:8px}button{cursor:pointer;font-weight:700}.approve{background:#27412e;color:white}.reject{background:#eee}.watch{background:#fff7df}@media(max-width:800px){form.grid{grid-template-columns:1fr 1fr}}@media(max-width:520px){form.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><h1>Revue des nouvelles sources</h1><p class="meta">Aucune source découverte n'entre dans les moyennes sans validation ici.</p><div class="nav"><a href="?status=review">À examiner</a><a href="?status=monitored_no_price">Sans tarif</a><a href="?status=approved">Acceptées</a><a href="?status=rejected">Refusées</a><a href="?status=all">Toutes</a></div><?php if($msg):?><p class="msg"><?=h($msg)?></p><?php endif;?><?php foreach($rows as $x):?><article class="card"><h2><?=h($x['title'])?></h2><p><a target="_blank" rel="noopener" href="<?=h($x['url'])?>"><?=h($x['url'])?></a></p><p class="meta">Statut : <b><?=h($x['status'])?></b> · Zone : <?=h($x['region'])?> <?=h($x['department'])?> · suggestion : <?=h($x['classification_hint'])?></p><p><?=h($x['reason'])?></p><div class="prices"><?php foreach($x['price_candidates']??[] as $p):?><span><?=h($p)?></span><?php endforeach;?></div><?php if(!in_array($x['status'],['approved','rejected'],true)):?><form method="post" class="grid"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="id" value="<?=h($x['id'])?>"><input name="provider" placeholder="Nom interne du prestataire"><input name="provider_type" placeholder="Type : cabinet / freelance…"><select name="scope"><option value="market">Marché comparable</option><option value="dpo" <?=($x['classification_hint']==='dpo'?'selected':'')?>>DPO — à part</option><option value="legal" <?=($x['classification_hint']==='legal'?'selected':'')?>>Expertise juridique — à part</option></select><input name="service" placeholder="Prestation" value="<?=h($x['classification_hint']==='dpo'?'DPO externalisé':'Audit / diagnostic RGPD')?>"><input name="segment" placeholder="Segment" value="TPE / PME"><select name="unit"><option>EUR/mission</option><option>EUR/jour</option><option>EUR/mois</option><option>EUR/an</option></select><input name="value" placeholder="Valeur numérique"><input name="price_text" placeholder="Libellé exact : 900 € HT"><button class="approve" name="action" value="approve">Accepter et ajouter</button><button class="watch" name="action" value="watch">Surveiller</button><button class="reject" name="action" value="reject">Refuser</button></form><?php endif;?></article><?php endforeach;?></div></body></html>